// This file is generated by AI.

// 目录浏览组件: 每次只打开一层目录 (文件夹 + 文件), 不递归扫描子目录。
// 进入子目录后才扫描该层; 支持返回上级、在当前目录内搜索、展平当前目录。
//
// 长目录**分页渲染**: 一次只挂前 PENDING_PAGE 行, 滚到底 (或点"加载更多") 再补一页。
// 资源目录动辄上千个文件, 一次性渲染出来会卡住整个界面 —— 磁盘读取其实很快,
// 卡的是几千个 DOM 节点加同样多的缩略图请求。

import {
  ChevronDownRegular,
  ChevronRightRegular,
  FolderRegular,
  HomeRegular,
  MoreVerticalRegular,
  ArrowUpRegular,
} from '@fluentui/react-icons';
import { useEffect, useRef, useState, type ReactNode } from 'react';

import { ContextMenu, type ContextMenuItem } from './ContextMenu';
import { fs } from '../lib/fs';
import { JSON_EXT, kindFor, type FileKind } from '../lib/fileKind';
import { relativeDirectoryPath, samePath } from '../lib/paths';

/** 一次渲染多少行; 滚到接近底部时再补一页 */
export const FILE_TREE_PAGE_SIZE = 120;

export interface FileNode {
  name: string;
  path: string;
  rel: string;
  isDirectory: boolean;
  kind: FileKind;
}

export interface FileTreeViewState {
  currentRel: string;
  query: string;
  flat: boolean;
  visibleCount: number;
  scrollTop: number;
}

export type FileTreeViewStateCache = Map<string, FileTreeViewState>;

export interface FileTreeRevealRequest {
  id: number;
  path: string;
}

/** 长名称中间省略: 保留开头与扩展名后缀。 */
export function middleEllipsis(text: string, maxLen: number): string {
  if (text.length <= maxLen) return text;
  const dot = text.lastIndexOf('.');
  const hasExt = dot > 0 && dot < text.length - 1;
  const ext = hasExt ? text.slice(dot) : '';
  const stem = hasExt ? text.slice(0, dot) : text;
  const avail = maxLen - ext.length - 3; // 3 = "..."
  if (avail < 4) return `${text.slice(0, Math.max(1, maxLen - 3))}...`;
  const keepHead = Math.ceil(avail / 2);
  const keepTail = avail - keepHead;
  return `${stem.slice(0, keepHead)}...${stem.slice(stem.length - keepTail)}${ext}`;
}

export const KIND_BADGE: Record<FileKind, string> = {
  image: 'IMG',
  audio: '♪',
  video: '▶',
  text: 'TXT',
  scene: 'SCN',
  other: '?',
};

export function badgeFor(name: string, kind: FileKind): string {
  const extension = name.slice(name.lastIndexOf('.') + 1).toLowerCase();
  if (JSON_EXT.includes(extension)) return 'JSON';
  if (kind === 'text' && extension) return extension.toUpperCase();
  return KIND_BADGE[kind];
}

async function recursiveFiles(dir: string, baseRel: string): Promise<FileNode[]> {
  const result: FileNode[] = [];
  async function walk(d: string, rel: string): Promise<void> {
    let entries: { name: string; isDirectory: boolean }[];
    try {
      entries = await fs.readDir(d);
    } catch {
      return;
    }
    entries.sort((a, b) => a.name.localeCompare(b.name));
    for (const e of entries) {
      const full = `${d}\\${e.name}`;
      const childRel = rel ? `${rel}/${e.name}` : e.name;
      if (e.isDirectory) {
        await walk(full, childRel);
      } else {
        result.push({ name: e.name, path: full, rel: childRel, isDirectory: false, kind: kindFor(e.name) });
      }
    }
  }
  await walk(dir, baseRel);
  return result;
}

interface FileTreeProps {
  rootPath: string;
  onOpen: (file: FileNode) => void;
  onDoubleClick?: (file: FileNode) => void;
  onDirectoryChange?: (path: string) => void;
  selectedPath?: string | null;
  revealRequest?: FileTreeRevealRequest | null;
  onRevealComplete?: (id: number) => void;
  excludeTop?: (name: string) => boolean;
  assetUrl?: (rel: string) => string | undefined;
  /** 内容变更 (新建/重命名/删除) 后递增, 强制重新加载当前目录 */
  refreshKey?: number;
  /** 可选文件过滤器 (目录始终保留) */
  includeFile?: (node: FileNode) => boolean;
  /** 编辑页生命周期内的视图状态缓存 */
  viewStateCache?: FileTreeViewStateCache;
  viewStateKey?: string;
  /** 工具栏右侧下拉菜单项 (返回上级按钮与展平按钮独立保留在工具栏上) */
  menu?: (currentDir: string) => ContextMenuItem[];
  /** 列表项右键菜单回调 (文件与文件夹均触发) */
  onItemContextMenu?: (node: FileNode, e: React.MouseEvent) => void;
  /** 文件行右侧附加徽标 (如 git 更改类型 / 诊断数) */
  badge?: (node: FileNode) => ReactNode;
  /** 自定义工具栏与列表的摆放方式; 缺省时工具栏在列表上方 (上下堆叠) */
  header?: (toolbar: ReactNode, list: ReactNode) => ReactNode;
  /** 列表空白区域右键菜单 */
  onBlankContextMenu?: (currentDir: string, event: React.MouseEvent<HTMLDivElement>) => void;
  /** 列表空白区域释放拖拽文件/目录 */
  onDropFiles?: (currentDir: string, event: React.DragEvent<HTMLDivElement>) => void;
}

export function FileTree({
  rootPath,
  onOpen,
  onDoubleClick,
  onDirectoryChange,
  selectedPath,
  revealRequest,
  onRevealComplete,
  excludeTop,
  assetUrl,
  refreshKey = 0,
  includeFile,
  viewStateCache,
  viewStateKey,
  menu,
  onItemContextMenu,
  badge,
  header,
  onBlankContextMenu,
  onDropFiles,
}: FileTreeProps) {
  const initialView = useRef(viewStateCache && viewStateKey ? viewStateCache.get(viewStateKey) : undefined);
  const [currentRel, setCurrentRel] = useState(initialView.current?.currentRel ?? '');
  const [dirEntries, setDirEntries] = useState<FileNode[]>([]);
  const [loadedDirectory, setLoadedDirectory] = useState<string | null>(null);
  const [query, setQuery] = useState(initialView.current?.query ?? '');
  const [flat, setFlat] = useState(initialView.current?.flat ?? false);
  const [flatEntries, setFlatEntries] = useState<FileNode[] | null>(null);
  const [searchResults, setSearchResults] = useState<FileNode[] | null>(null);
  const [localRefreshKey, setLocalRefreshKey] = useState(0);
  /** 当前渲染了多少行 (分页渲染, 见 FILE_TREE_PAGE_SIZE) */
  const [visibleCount, setVisibleCount] = useState(initialView.current?.visibleCount ?? FILE_TREE_PAGE_SIZE);
  const listRef = useRef<HTMLDivElement>(null);
  const restoredScroll = useRef(false);
  const previousView = useRef<{ currentAbs: string; query: string; flat: boolean } | null>(null);
  const previousSelectedPath = useRef(selectedPath);
  const [revealedPath, setRevealedPath] = useState<string | null>(null);

  const currentAbs = currentRel ? `${rootPath}\\${currentRel.replace(/\//g, '\\')}` : rootPath;
  const refreshVersion = refreshKey + localRefreshKey;

  useEffect(() => {
    if (previousSelectedPath.current !== selectedPath) setRevealedPath(null);
    previousSelectedPath.current = selectedPath;
  }, [selectedPath]);

  useEffect(() => {
    if (!revealRequest) return;
    const directoryRel = relativeDirectoryPath(rootPath, revealRequest.path);
    if (directoryRel === null) {
      onRevealComplete?.(revealRequest.id);
      return;
    }

    setRevealedPath(revealRequest.path);
    setQuery('');
    setFlat(false);
    setSearchResults(null);
    setVisibleCount(FILE_TREE_PAGE_SIZE);
    restoredScroll.current = true;
    setCurrentRel(directoryRel);
  }, [onRevealComplete, revealRequest, rootPath]);

  useEffect(() => {
    onDirectoryChange?.(currentAbs);
  }, [currentAbs, onDirectoryChange]);

  // 自动刷新: 监听当前目录变化并在新事件后重建列表；若当前目录被移动/删除则回退到最近存在的祖先目录。
  /*
   * 只有"展平/搜索"这两种视图才需要递归监听。
   *
   * 普通列表里只有本层的条目, 子目录内部的变化不会影响任何一行 (子目录行的名字只有在它
   * 本身被改名/删除时才变, 那是本层事件); 而展平/搜索的结果**包含子目录里的文件**, 那才
   * 需要递归。递归监听会把整棵子树的监视器都挂上 —— 资源目录动辄上千文件, 每进一次目录
   * 都要重挂一遍, 正是"进目录卡一下"的来源。
   */
  const watchRecursively = flat;
  useEffect(() => {
    let cancelled = false;
    let unwatch: (() => void) | null = null;
    let timer: ReturnType<typeof setTimeout> | null = null;

    const schedule = () => {
      if (cancelled) return;
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => {
        if (!cancelled) setLocalRefreshKey((value) => value + 1);
      }, 160);
    };

    void (async () => {
      try {
        unwatch = await import('@tauri-apps/plugin-fs').then(({ watch }) =>
          watch([currentAbs], () => schedule(), { recursive: watchRecursively, delayMs: 150 })
        );
      } catch {
        // 监听失败时直接忽略，交给外部手动刷新兜底。
      }
    })();

    return () => {
      cancelled = true;
      if (timer) clearTimeout(timer);
      if (unwatch) unwatch();
    };
  }, [currentAbs, watchRecursively]);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const exists = await fs.exists(currentAbs);
      if (cancelled || exists.exists) return;
      const segments = currentRel ? currentRel.split('/') : [];
      for (let i = segments.length; i >= 0; i -= 1) {
        const rel = segments.slice(0, i).join('/');
        const probe = rel ? `${rootPath}\\${rel.replace(/\//g, '\\')}` : rootPath;
        const probeExists = await fs.exists(probe);
        if (!cancelled && probeExists.exists) {
          setCurrentRel(rel);
          return;
        }
      }
      if (!cancelled) setCurrentRel('');
    })();
    return () => {
      cancelled = true;
    };
  }, [currentAbs, currentRel, rootPath, refreshVersion]);

  // 加载当前单层目录
  useEffect(() => {
    let cancelled = false;
    (async () => {
      let entries: { name: string; isDirectory: boolean }[];
      try {
        entries = await fs.readDir(currentAbs);
      } catch {
        entries = [];
      }
      if (cancelled) return;
      entries.sort((a, b) => (a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1));
      const nodes = entries
        .filter((e) => !(currentRel === '' && excludeTop && excludeTop(e.name)))
        .map((e) => ({
          name: e.name,
          path: `${currentAbs}\\${e.name}`,
          rel: currentRel ? `${currentRel}/${e.name}` : e.name,
          isDirectory: e.isDirectory,
          kind: e.isDirectory ? 'other' : kindFor(e.name),
        }))
        .filter((node) => node.isDirectory || !includeFile || includeFile(node));
      const revealIndex = revealRequest ? nodes.findIndex((node) => samePath(node.path, revealRequest.path)) : -1;
      if (revealIndex >= 0) setVisibleCount((count) => Math.max(count, revealIndex + 1));
      setDirEntries(nodes);
      setLoadedDirectory(currentAbs);
    })();
    return () => {
      cancelled = true;
    };
  }, [currentAbs, currentRel, excludeTop, includeFile, refreshVersion, revealRequest]);

  // 展平: 递归列出当前目录下所有文件
  useEffect(() => {
    if (!flat) {
      setFlatEntries(null);
      return;
    }
    let cancelled = false;
    void recursiveFiles(currentAbs, currentRel).then((files) => {
      if (!cancelled) {
        setFlatEntries(
          files.filter(
            (file) =>
              (!includeFile || includeFile(file)) &&
              !(currentRel === '' && excludeTop && excludeTop(file.rel.split('/')[0]))
          )
        );
      }
    });
    return () => {
      cancelled = true;
    };
  }, [flat, currentAbs, currentRel, excludeTop, includeFile, refreshVersion]);

  // 搜索: 在当前目录内递归过滤文件
  useEffect(() => {
    const q = query.trim().toLowerCase();
    if (!q) {
      setSearchResults(null);
      return;
    }
    const source = flat ? flatEntries : dirEntries.filter((entry) => !entry.isDirectory);
    if (!source) {
      setSearchResults(null);
      return;
    }
    setSearchResults(
      source.filter((file) => file.name.toLowerCase().includes(q) || file.rel.toLowerCase().includes(q))
    );
  }, [query, flat, flatEntries, dirEntries]);

  const resetView = () => {
    setQuery('');
    setFlat(false);
  };

  useEffect(() => {
    if (!viewStateCache || !viewStateKey) return;
    const previous = viewStateCache.get(viewStateKey);
    viewStateCache.set(viewStateKey, {
      currentRel,
      query,
      flat,
      visibleCount,
      scrollTop: listRef.current?.scrollTop ?? previous?.scrollTop ?? 0,
    });
  }, [viewStateCache, viewStateKey, currentRel, query, flat, visibleCount]);

  useEffect(() => {
    const previous = previousView.current;
    if (previous && (previous.currentAbs !== currentAbs || previous.query !== query || previous.flat !== flat)) {
      if (listRef.current) listRef.current.scrollTop = 0;
      setVisibleCount(FILE_TREE_PAGE_SIZE);
    }
    previousView.current = { currentAbs, query, flat };
  }, [currentAbs, query, flat]);

  const viewReady =
    loadedDirectory === currentAbs && (!flat || flatEntries !== null) && (!query.trim() || searchResults !== null);

  useEffect(() => {
    if (!revealRequest || !viewReady || flat || query.trim()) return;
    const directoryRel = relativeDirectoryPath(rootPath, revealRequest.path);
    const expectedAbs = directoryRel ? `${rootPath}\\${directoryRel.replace(/\//g, '\\')}` : rootPath;
    if (!samePath(currentAbs, expectedAbs)) return;

    const target = [...(listRef.current?.querySelectorAll<HTMLElement>('.file-tree-file[data-file-path]') ?? [])].find(
      (node) => samePath(node.dataset['filePath'] ?? '', revealRequest.path)
    );
    const targetIndex = dirEntries.findIndex((node) => samePath(node.path, revealRequest.path));
    if (targetIndex >= visibleCount) return;
    target?.scrollIntoView({ block: 'nearest' });
    onRevealComplete?.(revealRequest.id);
  }, [currentAbs, dirEntries, flat, onRevealComplete, query, revealRequest, rootPath, viewReady, visibleCount]);
  useEffect(() => {
    if (!viewReady || restoredScroll.current) return;
    if (listRef.current) listRef.current.scrollTop = initialView.current?.scrollTop ?? 0;
    restoredScroll.current = true;
  }, [viewReady]);

  const enterDir = (name: string) => {
    setRevealedPath(null);
    setCurrentRel((prev) => (prev ? `${prev}/${name}` : name));
    resetView();
  };

  const goUp = () => {
    setRevealedPath(null);
    setCurrentRel((prev) => (prev.includes('/') ? prev.slice(0, prev.lastIndexOf('/')) : ''));
    resetView();
  };

  const goToRoot = () => {
    setRevealedPath(null);
    setCurrentRel('');
    resetView();
  };

  // 展示列表: 搜索结果 > 展平结果 > 单层目录
  let list: FileNode[];
  let showPath = false;
  if (searchResults) {
    list = searchResults;
    showPath = true;
  } else if (flatEntries) {
    list = flatEntries;
    showPath = true;
  } else {
    list = dirEntries;
  }

  const visibleList = list.slice(0, visibleCount);
  const hasMore = list.length > visibleList.length;

  const loadMore = () => setVisibleCount((count) => count + FILE_TREE_PAGE_SIZE);

  /*
   * 滚到接近底部就补一页。
   *
   * 不用 IntersectionObserver 是因为滚动容器就是列表自己 (`.file-tree-list`), 直接读
   * scrollTop 最直白, 也少一层观察器生命周期; 列表不够长 (没得滚) 时靠底部的
   * "加载更多"按钮兜底。
   */
  const onListScroll = (event: React.UIEvent<HTMLDivElement>) => {
    const el = event.currentTarget;
    if (viewStateCache && viewStateKey) {
      viewStateCache.set(viewStateKey, {
        currentRel,
        query,
        flat,
        visibleCount,
        scrollTop: el.scrollTop,
      });
    }
    if (hasMore && el.scrollHeight - el.scrollTop - el.clientHeight < 240) loadMore();
  };

  // 展平/搜索时展示"从当前位置出发"的相对路径 (去掉从根到当前目录的前缀)
  const displayRel = (node: FileNode): string => {
    const base = currentRel ? `${currentRel}/` : '';
    return node.rel.startsWith(base) ? node.rel.slice(base.length) : node.rel;
  };

  const fileRow = (node: FileNode) => {
    const displayText = showPath ? displayRel(node) : node.name;
    return (
      <button
        key={node.path}
        data-file-path={node.path}
        className={`file-tree-file${samePath(node.path, revealedPath ?? selectedPath ?? '') ? ' active' : ''}`}
        onClick={() => {
          setRevealedPath(null);
          onOpen(node);
        }}
        onDoubleClick={() => onDoubleClick?.(node)}
        onContextMenu={(e) => {
          e.stopPropagation();
          onItemContextMenu?.(node, e);
        }}
        title={node.rel}
      >
        {node.kind === 'image' && assetUrl ? (
          <img className="resource-thumb" src={assetUrl(node.rel)} alt="" loading="lazy" />
        ) : (
          <span className="resource-badge">{badgeFor(node.name, node.kind)}</span>
        )}
        <span className="resource-name" title={displayText}>
          {middleEllipsis(displayText, 30)}
        </span>
        {badge ? badge(node) : null}
      </button>
    );
  };

  const [menuOpen, setMenuOpen] = useState(false);
  const menuBtnRef = useRef<HTMLButtonElement>(null);
  const [menuPos, setMenuPos] = useState<{ x: number; y: number } | null>(null);
  const [pathMenuPos, setPathMenuPos] = useState<{ x: number; y: number } | null>(null);

  // 关闭下拉菜单: 点击遮罩 / Esc / 窗口变化
  useEffect(() => {
    if (!menuOpen) return;
    const close = () => {
      setMenuOpen(false);
      setMenuPos(null);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    window.addEventListener('keydown', onKey);
    window.addEventListener('resize', close);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('resize', close);
    };
  }, [menuOpen]);

  const openToolbarMenu = () => {
    const rect = menuBtnRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = Math.max(0, Math.min(rect.right - 170, window.innerWidth - 180));
    const y = Math.min(rect.bottom + 4, window.innerHeight - 160);
    setMenuPos({ x, y });
    setMenuOpen(true);
  };

  const openPathMenu = (event: React.MouseEvent<HTMLButtonElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    setPathMenuPos({ x: rect.left, y: rect.bottom + 4 });
  };

  const navigateTo = (rel: string) => {
    setRevealedPath(null);
    setCurrentRel(rel);
    resetView();
  };

  const pathSegments = currentRel ? currentRel.split('/') : [];
  const pathMenuItems: ContextMenuItem[] = [
    {
      key: 'root',
      label: '根目录',
      title: rootPath,
      onClick: () => navigateTo(''),
    },
    ...pathSegments.map((segment, index) => {
      const rel = pathSegments.slice(0, index + 1).join('/');
      return {
        key: `directory-${index}`,
        label: segment,
        title: rel,
        onClick: () => navigateTo(rel),
      };
    }),
  ];

  const toolbar = (
    <div className="file-tree-toolbar">
      <button className="file-tree-icon-btn" title="返回根目录" disabled={currentRel === ''} onClick={goToRoot}>
        <HomeRegular />
      </button>
      <button
        type="button"
        className="file-tree-path"
        title={currentRel || '根目录'}
        aria-haspopup="menu"
        aria-expanded={pathMenuPos !== null}
        onClick={openPathMenu}
      >
        <span className="file-tree-path-label">{pathSegments.at(-1) || '根目录'}</span>
        <ChevronDownRegular />
      </button>
      {pathMenuPos ? (
        <ContextMenu x={pathMenuPos.x} y={pathMenuPos.y} items={pathMenuItems} onClose={() => setPathMenuPos(null)} />
      ) : null}
      <input
        className="file-tree-search"
        type="text"
        placeholder={flat ? '在当前目录中递归搜索...' : '在当前目录中搜索...'}
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <button
        className={`file-tree-flatten-btn${flat ? ' active' : ''}`}
        title="展平当前目录"
        onClick={() => {
          setQuery('');
          setFlat((v) => !v);
        }}
      >
        展平
      </button>
      {menu ? (
        <button ref={menuBtnRef} className="file-tree-icon-btn" title="更多操作" onClick={openToolbarMenu}>
          <MoreVerticalRegular />
        </button>
      ) : null}
      {menuOpen && menu ? (
        <ContextMenu
          x={menuPos?.x ?? 0}
          y={menuPos?.y ?? 0}
          items={menu(currentAbs)}
          onClose={() => {
            setMenuOpen(false);
            setMenuPos(null);
          }}
        />
      ) : null}
    </div>
  );

  const listNode = (
    <div
      ref={listRef}
      className="file-tree-list"
      onScroll={onListScroll}
      onContextMenu={(event) => {
        event.preventDefault();
        if (onBlankContextMenu) onBlankContextMenu(currentAbs, event);
      }}
      onDragOver={(event) => {
        if (onDropFiles) {
          event.preventDefault();
          event.dataTransfer.dropEffect = 'copy';
        }
      }}
      onDrop={(event) => {
        if (onDropFiles) {
          event.preventDefault();
          onDropFiles(currentAbs, event);
        }
      }}
    >
      {currentRel ? (
        <button type="button" className="file-tree-parent" onClick={goUp} title="返回上一级目录">
          <ArrowUpRegular />
          <span>返回上一级</span>
        </button>
      ) : null}
      {list.length === 0 ? (
        <span className="muted">{searchResults || flatEntries ? '无匹配项' : '空目录'}</span>
      ) : searchResults || flatEntries ? (
        visibleList.map(fileRow)
      ) : (
        visibleList.map((node) =>
          node.isDirectory ? (
            <div
              key={node.path}
              className="file-tree-dir"
              onClick={() => enterDir(node.name)}
              onContextMenu={(e) => {
                e.stopPropagation();
                onItemContextMenu?.(node, e);
              }}
              title={node.rel}
            >
              <span className="file-tree-dir-icon" aria-hidden="true">
                <FolderRegular />
              </span>
              <span className="file-tree-dir-name" title={node.name}>
                {middleEllipsis(node.name, 30)}
              </span>
              <ChevronRightRegular className="file-tree-dir-chevron" />
            </div>
          ) : (
            fileRow(node)
          )
        )
      )}

      {hasMore ? (
        <div className="file-tree-more">
          <span className="file-tree-more-count">
            已显示 {visibleList.length} / {list.length}
          </span>
          <button type="button" className="file-tree-more-btn" onClick={loadMore}>
            加载更多
          </button>
        </div>
      ) : null}
    </div>
  );

  return (
    <div className="file-tree">
      {header ? (
        header(toolbar, listNode)
      ) : (
        <>
          {toolbar}
          {listNode}
        </>
      )}
    </div>
  );
}
